#include <chrono>

#include <gtest/gtest.h>

#include "bench/drop.hpp"

using namespace std::chrono_literals;

TEST(Dropper, DropsFromTheCueUpToButNotIncludingTheEnd) {
  bench::Dropper relay;
  relay.drop_for({1s}, 200ms);
  EXPECT_FALSE(relay.forward({1s}));
  EXPECT_FALSE(relay.forward({1s + 200ms - 1ns}));
  EXPECT_TRUE(relay.forward({1s + 200ms}));
}

#include <array>
#include <chrono>
#include <compare>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>

namespace bench {

// From bench/time.hpp: a reading of a node's clock, in nanoseconds since that clock's zero.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

// bench/drop.hpp: which messages a relay lets through. It reads no clock; the caller passes the
// arrival time in, as the supervisor's rules do.
class Dropper {
 public:
  // Starts dropping at now, for length. A cue while a drop is running replaces it.
  void drop_for(Time now, std::chrono::nanoseconds length) {
    window_ = Window{.start = now, .end = {now.since_epoch + length}};
  }

  // Half open: a message at the cue is dropped, one at the end of the window is forwarded. A
  // clock reading before the cue ends the drop, so a simulation that was reset forwards again.
  [[nodiscard]] bool dropping(Time now) const {
    return window_ && window_->start <= now && now < window_->end;
  }

  // Whether the message that arrived at now goes on, counting both answers.
  [[nodiscard]] bool forward(Time now) {
    if (dropping(now)) {
      ++dropped_;
      return false;
    }
    ++forwarded_;
    return true;
  }

  [[nodiscard]] std::int64_t forwarded() const { return forwarded_; }
  [[nodiscard]] std::int64_t dropped() const { return dropped_; }

  // When the drop ends, for the log and the service's reply.
  [[nodiscard]] std::optional<Time> ends_at() const {
    if (!window_) return std::nullopt;
    return window_->end;
  }

 private:
  struct Window {
    Time start;
    Time end;
  };

  std::optional<Window> window_;
  std::int64_t forwarded_ = 0;
  std::int64_t dropped_ = 0;
};

}  // namespace bench

int main() {
  using namespace std::chrono_literals;
  const auto at = [](std::chrono::nanoseconds t) { return bench::Time{t}; };

  bench::Dropper relay;
  constexpr std::array<std::chrono::milliseconds, 9> arrivals{0ms, 50ms, 100ms, 150ms, 200ms,
                                                              250ms, 300ms, 350ms, 400ms};
  for (const auto arrival : arrivals) {
    if (arrival == 150ms) {
      relay.drop_for(at(arrival), 200ms);
      std::cout << std::format("cue at {} ms: dropping until {} ms\n", arrival.count(),
                               relay.ends_at()->since_epoch / 1ms);
    }
    std::cout << std::format("{:3} ms: {}\n", arrival.count(), relay.forward(at(arrival)) ? "forward" : "drop");
  }

  std::cout << std::format("clock back to 100 ms: {}\n", relay.forward(at(100ms)) ? "forward" : "drop");
  std::cout << std::format("dropping at 350 ms minus 1 ns: {}\n", relay.dropping(at(350ms - 1ns)));
  std::cout << std::format("dropping at 350 ms: {}\n", relay.dropping(at(350ms)));
  std::cout << std::format("forwarded {}, dropped {}\n", relay.forwarded(), relay.dropped());
}

