namespace bench_nodes {

using Trigger = example_interfaces::srv::Trigger;

// Republishes the bridge's /odom_raw as /odom, and stops for drop_ms when its service is called.
// That is how a scenario takes odometry away from the supervisor without touching the simulator
// or the bridge.
class OdomRelay : public rclcpp::Node {
 public:
  explicit OdomRelay(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("odom_relay", options),
        drop_(std::chrono::milliseconds(declare_parameter<std::int64_t>("drop_ms", 2000))) {
    const rclcpp::QoS qos(rclcpp::KeepLast(10));
    publisher_ = create_publisher<nav_msgs::msg::Odometry>("odom", qos);
    subscription_ = create_subscription<nav_msgs::msg::Odometry>(
        "odom_raw", qos, [this](const nav_msgs::msg::Odometry& message) { on_odometry(message); });
    service_ = create_service<Trigger>(
        "~/drop", [this](const std::shared_ptr<Trigger::Request> request, std::shared_ptr<Trigger::Response> response) {
          on_drop(*request, *response);
        });
  }

  [[nodiscard]] std::int64_t forwarded() const { return dropper_.forwarded(); }
  [[nodiscard]] std::int64_t dropped() const { return dropper_.dropped(); }

 private:
  [[nodiscard]] bench::Time clock_time() const { return {std::chrono::nanoseconds(now().nanoseconds())}; }

  void on_odometry(const nav_msgs::msg::Odometry& message) {
    if (dropper_.forward(clock_time())) publisher_->publish(message);
  }

  void on_drop(const Trigger::Request&, Trigger::Response& response) {
    dropper_.drop_for(clock_time(), drop_);
    const double ends_s = std::chrono::duration<double>(dropper_.ends_at()->since_epoch).count();
    response.success = true;
    response.message = std::format("dropping /odom until {:.3f} s of this node's clock", ends_s);
    RCLCPP_WARN(get_logger(), "%s", response.message.c_str());
  }

  std::chrono::nanoseconds drop_;
  bench::Dropper dropper_;
  rclcpp::Publisher<nav_msgs::msg::Odometry>::SharedPtr publisher_;
  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr subscription_;
  rclcpp::Service<Trigger>::SharedPtr service_;
};

}  // namespace bench_nodes

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<bench_nodes::OdomRelay>());
  rclcpp::shutdown();
}

// In the fixture: fire the cue and wait for the answer, without ever blocking on the future.
bool cue() {
  auto future = client->async_send_request(std::make_shared<Trigger::Request>());
  if (!spin_until([&] { return future.wait_for(std::chrono::seconds(0)) == std::future_status::ready; })) {
    return false;
  }
  return future.get()->success;
}

TEST_F(OdomRelayTest, StopsForwardingForTheLengthOfTheDrop) {
  ASSERT_TRUE(spin_until([&] { return relay->forwarded() >= 5; }));
  ASSERT_TRUE(cue());
  const std::int64_t before = fake->received();
  ASSERT_TRUE(spin_until([&] { return relay->dropped() >= 5; }));
  EXPECT_EQ(fake->received(), before);
}
